CREATE TABLE IF NOT EXISTS zukan_trust_anchors ( trust_anchor_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, anchor_method TEXT NOT NULL, external_reference TEXT NOT NULL, assurance_level INTEGER NOT NULL, evidence_content_object_id TEXT REFERENCES zukan_content_objects(content_object_id) ON DELETE SET NULL, valid_from TEXT NOT NULL, valid_to TEXT, anchor_status TEXT NOT NULL DEFAULT 'active', policy_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (anchor_method IN ('official_domain','government_register','signed_agreement','authenticated_account','manual_institutional_review')), CHECK (assurance_level BETWEEN 0 AND 100), CHECK (anchor_status IN ('active','suspended','retired')), CHECK (valid_to IS NULL OR valid_to > valid_from) ); CREATE TABLE IF NOT EXISTS zukan_authority_assertions ( authority_assertion_id TEXT PRIMARY KEY, authority_subject_id TEXT NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, trust_anchor_id TEXT NOT NULL REFERENCES zukan_trust_anchors(trust_anchor_id) ON DELETE RESTRICT, predicate_uri TEXT, predicate_version INTEGER, subject_scope_json TEXT NOT NULL DEFAULT '{}', jurisdiction_json TEXT NOT NULL DEFAULT '{}', authority_rank INTEGER NOT NULL DEFAULT 0, valid_from TEXT NOT NULL, valid_to TEXT, assertion_status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (authority_rank BETWEEN 0 AND 1000), CHECK (assertion_status IN ('active','suspended','retired')), CHECK (valid_to IS NULL OR valid_to > valid_from), CHECK (json_valid(subject_scope_json)), CHECK (json_valid(jurisdiction_json)), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE TABLE IF NOT EXISTS zukan_authority_revocation_events ( revocation_event_id TEXT PRIMARY KEY, authority_assertion_id TEXT NOT NULL REFERENCES zukan_authority_assertions(authority_assertion_id) ON DELETE RESTRICT, revocation_mode TEXT NOT NULL, effective_at TEXT NOT NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reason TEXT NOT NULL, impact_json TEXT NOT NULL DEFAULT '{}', CHECK (revocation_mode IN ('prospective','retroactive')), CHECK (json_valid(impact_json)) ); CREATE TABLE IF NOT EXISTS zukan_claim_authority_links ( claim_revision_id TEXT NOT NULL REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE RESTRICT, authority_assertion_id TEXT NOT NULL REFERENCES zukan_authority_assertions(authority_assertion_id) ON DELETE RESTRICT, PRIMARY KEY (claim_revision_id, authority_assertion_id) ); CREATE TABLE IF NOT EXISTS zukan_resolution_policy_versions ( resolution_policy_id TEXT PRIMARY KEY, policy_key TEXT NOT NULL, policy_version INTEGER NOT NULL, rules_json TEXT NOT NULL, tie_break_rules_json TEXT NOT NULL DEFAULT '[]', policy_status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (policy_version >= 1), CHECK (policy_status IN ('proposed','active','deprecated','retired')), CHECK (json_valid(rules_json)), CHECK (json_valid(tie_break_rules_json)), UNIQUE (policy_key, policy_version) ); CREATE TABLE IF NOT EXISTS zukan_resolution_runs ( resolution_run_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, workspace_id TEXT, subject_id TEXT NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, predicate_uri TEXT NOT NULL, predicate_version INTEGER NOT NULL, candidate_query_id TEXT NOT NULL, candidate_query_version INTEGER NOT NULL, claim_store_snapshot_token TEXT NOT NULL, claim_store_sequence_watermark INTEGER NOT NULL, recorded_time_watermark TEXT NOT NULL, predicate_registry_snapshot_hash TEXT NOT NULL, authority_snapshot_hash TEXT NOT NULL, resolution_policy_id TEXT NOT NULL REFERENCES zukan_resolution_policy_versions(resolution_policy_id) ON DELETE RESTRICT, evaluator_build TEXT NOT NULL, target_time_from TEXT, target_time_to TEXT, execution_context_json TEXT NOT NULL DEFAULT '{}', input_hash TEXT NOT NULL, output_hash TEXT NOT NULL, run_status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (candidate_query_version >= 1), CHECK (claim_store_sequence_watermark >= 0), CHECK (length(predicate_registry_snapshot_hash) = 64), CHECK (length(authority_snapshot_hash) = 64), CHECK (length(input_hash) = 64), CHECK (length(output_hash) = 64), CHECK (run_status IN ('empty','resolved','disputed','failed')), CHECK (json_valid(execution_context_json)), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE TABLE IF NOT EXISTS zukan_resolution_run_claims ( resolution_run_id TEXT NOT NULL REFERENCES zukan_resolution_runs(resolution_run_id) ON DELETE RESTRICT, claim_revision_id TEXT NOT NULL REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE RESTRICT, decision TEXT NOT NULL, reason_code TEXT, authority_rank INTEGER, candidate_ordinal INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (resolution_run_id, claim_revision_id), CHECK (decision IN ('candidate','accepted','rejected')), CHECK (candidate_ordinal >= 0) ); CREATE TABLE IF NOT EXISTS zukan_projection_snapshots ( projection_snapshot_id TEXT PRIMARY KEY, resolution_run_id TEXT NOT NULL REFERENCES zukan_resolution_runs(resolution_run_id) ON DELETE RESTRICT, snapshot_hash TEXT NOT NULL UNIQUE, reproducibility_at_issue TEXT NOT NULL DEFAULT 'full', issued_at TEXT NOT NULL, context_json TEXT NOT NULL DEFAULT '{}', CHECK (length(snapshot_hash) = 64), CHECK (reproducibility_at_issue IN ('full','redacted','degraded')), CHECK (json_valid(context_json)) ); CREATE TABLE IF NOT EXISTS zukan_projection_entries ( projection_snapshot_id TEXT NOT NULL REFERENCES zukan_projection_snapshots(projection_snapshot_id) ON DELETE RESTRICT, entry_key TEXT NOT NULL, claim_revision_id TEXT REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE RESTRICT, value_artifact_id TEXT REFERENCES zukan_value_artifacts(artifact_id) ON DELETE RESTRICT, entry_payload_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (projection_snapshot_id, entry_key), CHECK (json_valid(entry_payload_json)) ); CREATE TABLE IF NOT EXISTS zukan_publication_editions ( publication_edition_id TEXT PRIMARY KEY, publication_key TEXT NOT NULL, edition_label TEXT NOT NULL, projection_snapshot_id TEXT NOT NULL REFERENCES zukan_projection_snapshots(projection_snapshot_id) ON DELETE RESTRICT, manifest_hash TEXT NOT NULL UNIQUE, manifest_payload_json TEXT NOT NULL DEFAULT '{}', issued_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (length(manifest_hash) = 64), CHECK (json_valid(manifest_payload_json)) ); CREATE TRIGGER IF NOT EXISTS trg_zukan_resolution_runs_no_update BEFORE UPDATE ON zukan_resolution_runs BEGIN SELECT RAISE(ABORT, 'zukan_resolution_runs_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_resolution_runs_no_delete BEFORE DELETE ON zukan_resolution_runs BEGIN SELECT RAISE(ABORT, 'zukan_resolution_runs_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_projection_snapshots_no_update BEFORE UPDATE ON zukan_projection_snapshots BEGIN SELECT RAISE(ABORT, 'zukan_projection_snapshots_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_projection_snapshots_no_delete BEFORE DELETE ON zukan_projection_snapshots BEGIN SELECT RAISE(ABORT, 'zukan_projection_snapshots_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_projection_entries_no_update BEFORE UPDATE ON zukan_projection_entries BEGIN SELECT RAISE(ABORT, 'zukan_projection_entries_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_projection_entries_no_delete BEFORE DELETE ON zukan_projection_entries BEGIN SELECT RAISE(ABORT, 'zukan_projection_entries_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_authority_revocations_no_update BEFORE UPDATE ON zukan_authority_revocation_events BEGIN SELECT RAISE(ABORT, 'zukan_authority_revocations_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_authority_revocations_no_delete BEFORE DELETE ON zukan_authority_revocation_events BEGIN SELECT RAISE(ABORT, 'zukan_authority_revocations_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_resolution_policies_no_update BEFORE UPDATE ON zukan_resolution_policy_versions BEGIN SELECT RAISE(ABORT, 'zukan_resolution_policies_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_resolution_policies_no_delete BEFORE DELETE ON zukan_resolution_policy_versions BEGIN SELECT RAISE(ABORT, 'zukan_resolution_policies_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_resolution_run_claims_no_update BEFORE UPDATE ON zukan_resolution_run_claims BEGIN SELECT RAISE(ABORT, 'zukan_resolution_run_claims_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_resolution_run_claims_no_delete BEFORE DELETE ON zukan_resolution_run_claims BEGIN SELECT RAISE(ABORT, 'zukan_resolution_run_claims_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_publication_editions_no_update BEFORE UPDATE ON zukan_publication_editions BEGIN SELECT RAISE(ABORT, 'zukan_publication_editions_immutable'); END; CREATE TRIGGER IF NOT EXISTS trg_zukan_publication_editions_no_delete BEFORE DELETE ON zukan_publication_editions BEGIN SELECT RAISE(ABORT, 'zukan_publication_editions_immutable'); END;
